/**
 * FLAT Engine: Deterministic Finite Automaton (DFA) for Network Diagnosis
 * 
 * Formal Languages and Automata Theory (FLAT) Module:
 * Formally defines a 5-tuple M = (Q, Sigma, delta, q0, F) to parse and 
 * classify diagnostic symbol sequences generated by sequential network tests.
 */

// Alphabet Sigma
export const ALPHABET = {
  G: 'Gateway reachable',
  g: 'Gateway unreachable',
  D: 'DNS resolution successful',
  d: 'DNS resolution failed',
  S: 'Server/Destination reachable',
  s: 'Server/Destination unreachable',
  T: 'TCP port connection successful',
  t: 'TCP port connection failed'
};

// Set of States Q
export const STATES = {
  q0: { id: 'q0', label: 'Initial State', description: 'Start of network diagnostic pipeline' },
  q_G: { id: 'q_G', label: 'Gateway OK', description: 'Local gateway connection verified' },
  q_g: { id: 'q_g', label: 'Gateway Failure', description: 'Local default gateway or physical link failure', isAccepting: true, diagnosis: 'LOCAL_GATEWAY_FAILURE' },
  q_GD: { id: 'q_GD', label: 'DNS OK', description: 'Domain name successfully resolved to IP' },
  q_Gd: { id: 'q_Gd', label: 'DNS Failure', description: 'DNS resolution failed at gateway/upstream resolver', isAccepting: true, diagnosis: 'DNS_RESOLUTION_FAILURE' },
  q_GDS: { id: 'q_GDS', label: 'Server Reachable', description: 'Destination IP reachable across routing hops' },
  q_GDs: { id: 'q_GDs', label: 'Routing / Host Failure', description: 'Gateway and DNS work, but destination IP is unreachable', isAccepting: true, diagnosis: 'DESTINATION_UNREACHABLE' },
  q_GDST: { id: 'q_GDST', label: 'All Tests Passed', description: 'All network layers (Physical, IP, Transport) operational', isAccepting: true, diagnosis: 'ALL_OPERATIONAL' },
  q_GDSt: { id: 'q_GDSt', label: 'Port / Firewall Blocked', description: 'Destination is up, but target TCP service port is closed or filtered', isAccepting: true, diagnosis: 'PORT_FIREWALL_BLOCKED' },
  q_trap: { id: 'q_trap', label: 'Trap / Syntax Error', description: 'Invalid diagnostic sequence or protocol violation', isAccepting: false, diagnosis: 'INVALID_SEQUENCE' }
};

// Transition function delta: Q x Sigma -> Q
export const TRANSITIONS = {
  q0: {
    G: 'q_G',
    g: 'q_g'
  },
  q_G: {
    D: 'q_GD',
    d: 'q_Gd',
    S: 'q_GDS',
    s: 'q_GDs',
    T: 'q_GDST',
    t: 'q_GDSt'
  },
  q_GD: {
    S: 'q_GDS',
    s: 'q_GDs',
    T: 'q_GDST',
    t: 'q_GDSt'
  },
  q_GDS: {
    T: 'q_GDST',
    t: 'q_GDSt'
  },
  // Terminal states loop to trap on extra input
  q_g: {},
  q_Gd: {},
  q_GDs: {},
  q_GDSt: {},
  q_GDST: {},
  q_trap: {}
};

// Diagnostic outcome descriptions for accepting states
export const DIAGNOSTIC_OUTCOMES = {
  LOCAL_GATEWAY_FAILURE: {
    category: 'Local Network Failure',
    severity: 'Critical',
    summary: 'The local default gateway is unreachable. Network traffic cannot leave the host.',
    rootCause: 'Physical cable disconnected, Wi-Fi link dropped, or local router offline.',
    recommendation: 'Check Ethernet/Wi-Fi connection, verify local DHCP IP lease, reboot router.'
  },
  DNS_RESOLUTION_FAILURE: {
    category: 'DNS Failure',
    severity: 'High',
    summary: 'Gateway is reachable, but name resolution failed for the target hostname.',
    rootCause: 'Misconfigured DNS resolver, DNS cache corruption, or authoritative nameserver outage.',
    recommendation: 'Check /etc/resolv.conf or Windows DNS settings. Test with public DNS 8.8.8.8 / 1.1.1.1.'
  },
  DESTINATION_UNREACHABLE: {
    category: 'Routing / Remote Server Failure',
    severity: 'High',
    summary: 'Gateway and DNS are operational, but the target server does not respond to network probes.',
    rootCause: 'Upstream ISP routing outage, intermediate link failure, or remote server power loss.',
    recommendation: 'Inspect traceroute hops, check ISP status, confirm server public IP address.'
  },
  PORT_FIREWALL_BLOCKED: {
    category: 'Transport / Firewall Failure',
    severity: 'Medium',
    summary: 'Target host is alive, but TCP handshake failed on the requested application port.',
    rootCause: 'Remote service daemon is stopped, listening on a different port, or blocked by firewall/security group.',
    recommendation: 'Confirm target port number, check local/cloud firewall rules (iptables/UFW/AWS SG), ensure daemon is running.'
  },
  ALL_OPERATIONAL: {
    category: 'Healthy Connectivity',
    severity: 'None',
    summary: 'All connectivity checkpoints passed successfully. Gateway, DNS, IP routing, and TCP port responded.',
    rootCause: 'No connectivity defects detected.',
    recommendation: 'Network layer is healthy. If application issues persist, inspect application payload or TLS certificates.'
  },
  INVALID_SEQUENCE: {
    category: 'Grammar / Sequence Error',
    severity: 'Low',
    summary: 'The input sequence deviated from the diagnostic language grammar L(M).',
    rootCause: 'Tests executed out of topological order or invalid symbols provided.',
    recommendation: 'Execute diagnostic pipeline in proper order: Gateway -> DNS -> Host Reachability -> TCP Port.'
  }
};

/**
 * Normalizes input sequence by stripping whitespace and invalid characters.
 * @param {string} input - Raw sequence string, e.g. "G D S T"
 * @returns {string} Normalized uppercase string, e.g. "GDST"
 */
export function normalizeSequence(input) {
  if (!input || typeof input !== 'string') return '';
  return input.replace(/[^GgDdSsTt]/g, '');
}

/**
 * Runs the Deterministic Finite Automaton on an input sequence.
 * @param {string} rawSequence - Input sequence string (e.g. "Gd", "GDST", "g")
 * @returns {Object} Complete trace, state sequence, acceptance status, and diagnosis.
 */
export function runDFA(rawSequence) {
  const sequence = normalizeSequence(rawSequence);
  let currentState = 'q0';
  const trace = [];

  for (let i = 0; i < sequence.length; i++) {
    const symbol = sequence[i];
    const nextState = (TRANSITIONS[currentState] && TRANSITIONS[currentState][symbol]) || 'q_trap';

    trace.push({
      step: i + 1,
      symbol,
      symbolMeaning: ALPHABET[symbol] || 'Unknown Symbol',
      fromState: currentState,
      toState: nextState,
      toStateLabel: STATES[nextState].label,
      isAccepting: Boolean(STATES[nextState].isAccepting)
    });

    currentState = nextState;
    if (currentState === 'q_trap') {
      break;
    }
  }

  const stateObj = STATES[currentState] || STATES.q_trap;
  const isAccepted = Boolean(stateObj.isAccepting);
  const diagnosisCode = stateObj.diagnosis || 'INVALID_SEQUENCE';
  const outcome = DIAGNOSTIC_OUTCOMES[diagnosisCode] || DIAGNOSTIC_OUTCOMES.INVALID_SEQUENCE;

  return {
    inputSequence: sequence,
    rawInput: rawSequence,
    finalState: currentState,
    finalStateLabel: stateObj.label,
    isAccepted,
    diagnosisCode,
    outcome,
    trace,
    formalDefinition: {
      tuple: 'M = (Q, Σ, δ, q0, F)',
      statesCount: Object.keys(STATES).length,
      alphabet: Object.keys(ALPHABET),
      initialState: 'q0',
      acceptingStates: Object.values(STATES).filter(s => s.isAccepting).map(s => s.id)
    }
  };
}

/**
 * Converts a set of diagnostic test outcomes into a DFA sequence string.
 * @param {Object} results - Object with test booleans: gateway, dns, host, tcp
 * @returns {string} DFA sequence string, e.g. "GDST", "Gd", "g"
 */
export function buildDfaSequenceFromTests({ gateway, dns, host, tcp, targetIsIp = false }) {
  let sequence = '';

  // 1. Gateway
  if (gateway === false) {
    return 'g';
  } else if (gateway === true) {
    sequence += 'G';
  }

  // 2. DNS (only if target was a hostname)
  if (!targetIsIp) {
    if (dns === false) {
      sequence += 'd';
      return sequence;
    } else if (dns === true) {
      sequence += 'D';
    }
  }

  // 3. Server / Host Reachability (ICMP/route)
  if (host === false) {
    sequence += 's';
    return sequence;
  } else if (host === true) {
    sequence += 'S';
  }

  // 4. TCP Port
  if (tcp === false) {
    sequence += 't';
    return sequence;
  } else if (tcp === true) {
    sequence += 'T';
  }

  return sequence;
}

export default {
  ALPHABET,
  STATES,
  TRANSITIONS,
  DIAGNOSTIC_OUTCOMES,
  normalizeSequence,
  runDFA,
  buildDfaSequenceFromTests
};
